/* =====================================================================
   Banco de preguntas · Física 3 · S12 · Ley de Lenz, forma general de Faraday y generadores
   Plantillas parametrizadas, todas propias (source: 'propia'). Unidades SI.
   Convención: espira en la página, vista de frente; antihoraria ↔ campo inducido que sale.
   concept: true = conceptual. Cada numérica trae oracle(v, LM): la misma respuesta
   recalculada con LabMath.lenz (lo comprueba scripts/labs-math/lenz-direction.js).
   ===================================================================== */
(function () {
  var K = window.CBBankKit('f3', '12');
  var TAU = 2 * Math.PI;
  var SCI = ' Responde con notación científica.';
  function fx(v, d) { return Number(v.toFixed(d == null ? 2 : d)).toString(); }
  var LZ = function (LM) { return LM.lenz; };

  function distinct(q) {
    return function (v) {
      if (q.baseWhere && !q.baseWhere(v)) return false;
      var vals = [q.answer(v)].concat(Object.keys(q.mistakes).map(function (k) { return q.mistakes[k](v); }));
      for (var i = 0; i < vals.length; i++) {
        if (!isFinite(vals[i])) return false;
        for (var j = i + 1; j < vals.length; j++) {
          var big = Math.max(Math.abs(vals[i]), Math.abs(vals[j])), small = Math.min(Math.abs(vals[i]), Math.abs(vals[j]));
          if (Math.abs(vals[i] - vals[j]) <= Math.max(0.03 * big, small >= 0.09 ? 0.025 : 0)) return false;
        }
      }
      return true;
    };
  }
  function N(id, sub, d, vars, prompt, answer, why, o, oracle) {
    o = o || {};
    var q = K.N(id, sub, d, vars, prompt, answer, why, o);
    if (o.mistakes) { q.baseWhere = o.where; q.where = distinct(q); }
    q.oracle = oracle;
    return q;
  }
  var C = K.C;
  // Campo uniforme: k = 0…3 → [sale, crece], [sale, decrece], [entra, crece], [entra, decrece].
  var CS = [[true, true], [true, false], [false, true], [false, false]];
  function indOut(k) { return CS[k][0] !== CS[k][1]; }
  function curOf(k) { return indOut(k) ? 'Antihoraria' : 'Horaria'; }
  function otherCur(k) { return indOut(k) ? 'Horaria' : 'Antihoraria'; }
  function caseText(k) { return 'un campo uniforme que <strong>' + (CS[k][0] ? 'sale de' : 'entra en') + '</strong> la página y que <strong>' + (CS[k][1] ? 'aumenta' : 'disminuye') + '</strong>'; }

  var Q = [
    /* ======================= Ley de Lenz ======================= */
    C('le-enunciado', 'lenz', 1, 'La ley de Lenz dice que la corriente inducida…', 'produce un campo magnético que se opone al cambio del flujo',
      [['produce un campo magnético que refuerza el cambio del flujo', 'Si lo reforzara, se crearía energía de la nada.'], ['siempre circula en sentido horario', 'El sentido depende de cómo cambia el flujo.'], ['produce un campo siempre opuesto al campo externo', 'Se opone al cambio, no al campo: si el flujo decrece, apunta igual.']],
      'Oposición al cambio del flujo.'),
    C('le-signo', 'lenz', 1, '¿Qué parte de la ley de Faraday expresa la ley de Lenz?', 'El signo menos de $\\varepsilon = -N\\,d\\Phi/dt$',
      [['El factor $N$', '$N$ solo cuenta las vueltas.'], ['La derivada', 'La derivada da el tamaño; el sentido lo da el signo.'], ['El área de la espira', 'El área está en $\\Phi$.']],
      'El signo menos.'),
    C('le-energia', 'lenz', 2, '¿Por qué la corriente inducida no puede reforzar el cambio de flujo?', 'Porque se crearía energía de la nada, violando la conservación de la energía',
      [['Porque la carga no se conserva', 'La carga sí se conserva; el problema sería la energía.'], ['Porque las corrientes siempre son horarias', 'El sentido depende del cambio.'], ['Porque el campo magnético no hace trabajo', 'El argumento es de energía total: habría un ciclo que crea energía.']],
      'Lenz es conservación de la energía.'),
    C('le-tubo', 'lenz', 2, 'Un imán cae por un tubo vertical de cobre y otro igual por un tubo de plástico. ¿Cuál llega primero al suelo?', 'El del tubo de plástico',
      [['El del tubo de cobre, porque el cobre atrae al imán', 'El cobre no es atraído; las corrientes inducidas lo frenan.'], ['Llegan juntos', 'En el cobre se inducen corrientes que frenan al imán.'], ['Ninguno: el del cobre se queda flotando', 'Sí cae, solo que más despacio.']],
      'En el cobre se inducen corrientes que se oponen a la caída.'),
    C('le-acerca', 'lenz', 1, 'Acercas el polo N de un imán a una espira de cobre. La espira…', 'repele al imán',
      [['atrae al imán', 'Al acercarlo, el flujo crece y la espira se opone: lo empuja.'], ['no le hace nada, porque el cobre no es magnético', 'La corriente inducida produce un campo.'], ['lo atrae solo si es de hierro', 'La espira de cobre también lo repele, por la corriente inducida.']],
      'La espira presenta una cara N hacia el imán.'),
    C('le-aleja', 'lenz', 2, 'Alejas el polo N de un imán de una espira de cobre. La espira…', 'atrae al imán',
      [['repele al imán', 'Al alejarlo el flujo decrece; la espira se opone jalándolo.'], ['no hace nada', 'Mientras cambia el flujo hay corriente y fuerza.'], ['se calienta pero no hace fuerza', 'Hay corriente y hay fuerza.']],
      'Se opone al alejamiento: lo jala.'),
    C('le-cara', 'lenz', 3, 'Al acercar el polo S de un imán a una espira, la cara de la espira que mira al imán se comporta como…', 'un polo S, para repelerlo',
      [['un polo N, para atraerlo', 'Si lo atrajera, ayudaría al cambio.'], ['un polo N, para repelerlo', 'Un polo N atraería a un S.'], ['no tiene polaridad', 'Con corriente inducida, la espira es un imán.']],
      'Polos iguales se repelen: la espira se opone al acercamiento.'),
    C('le-trabajo', 'lenz', 2, 'Para acercar un imán a una espira cerrada a rapidez constante, tienes que…', 'empujar, y ese trabajo se convierte en calor en la espira',
      [['no hacer nada: la espira lo atrae', 'La espira lo repele.'], ['frenarlo, porque la espira lo acelera', 'Al revés: la espira se opone.'], ['empujar, pero el trabajo desaparece', 'La energía se conserva: termina como calor.']],
      'El trabajo externo es la energía eléctrica.'),
    C('le-abierta', 'lenz', 3, 'Acercas un imán a una espira de cobre que tiene un corte (no está cerrada). ¿Qué pasa?', 'Hay fem pero no corriente, así que la espira no hace fuerza sobre el imán',
      [['La espira repele al imán con más fuerza', 'Sin corriente no hay campo inducido ni fuerza.'], ['No hay fem', 'La fem aparece igual; lo que falta es la corriente.'], ['La espira atrae al imán', 'Sin corriente no hay fuerza.']],
      'Sin circuito cerrado no circula corriente.'),
    C('le-pendulo', 'lenz', 3, 'Una placa de aluminio cuelga como péndulo y oscila entre los polos de un imán. Si le haces cortes como peine, el péndulo…', 'se frena menos, porque los cortes impiden que circulen las corrientes inducidas',
      [['se frena más', 'Los cortes reducen las corrientes de Foucault y el frenado.'], ['se frena igual', 'Los cortes cambian los caminos de las corrientes.'], ['se acelera', 'Las corrientes inducidas nunca aceleran el movimiento.']],
      'Menos corriente inducida → menos fuerza que frena.'),
    C('le-rapido', 'lenz', 2, 'Si acercas el imán a la espira más rápido, la fuerza que hace la espira sobre el imán…', 'es mayor',
      [['es menor', 'Más rapidez → más fem → más corriente → más fuerza.'], ['no cambia', 'La corriente depende de $d\\Phi/dt$.'], ['cambia de sentido', 'Sigue oponiéndose al acercamiento.']],
      'La corriente es proporcional a la rapidez del cambio.'),
    C('le-cambio-no-campo', 'lenz', 2, 'Un compañero dice: «el campo inducido siempre apunta al revés que el campo del imán». ¿Tiene razón?', 'No: si el flujo disminuye, el campo inducido apunta igual que el del imán',
      [['Sí, siempre', 'Solo cuando el flujo crece.'], ['No: siempre apunta igual', 'Solo cuando el flujo decrece.'], ['Sí, salvo si el imán es muy fuerte', 'La intensidad no cambia la regla.']],
      'Se opone al cambio del flujo, no al campo.'),
    N('le-corriente', 'lenz', 2, { r: [2, 8, 1], dB: [0.2, 3, 0.2], R: [1, 20, 1] },
      function (v) { return 'Un anillo de $' + v.r + '\\ \\text{cm}$ de radio y $' + v.R + '\\ \\text{m}\\Omega$ de resistencia está en un campo perpendicular que crece a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Qué corriente circula, en A?'; },
      function (v) { return Math.PI * Math.pow(v.r / 100, 2) * v.dB / (v.R / 1000); }, '$I = \\pi r^2\\,(dB/dt)/R$.',
      { unit: 'A', mistakes: { mOhm: function (v) { return Math.PI * Math.pow(v.r / 100, 2) * v.dB / v.R; } }, feedback: [{ when: 'mOhm', say: 'La resistencia está en mΩ: divide entre $10^{-3}\\ \\Omega$.' }] },
      function (v, LM) { return LZ(LM).regionEmf(v.r / 100, 1, v.dB) / (v.R / 1000); }),
    N('le-potencia', 'lenz', 3, { r: [2, 8, 1], dB: [0.5, 3, 0.5], R: [5, 50, 5] },
      function (v) { return 'Un anillo de $' + v.r + '\\ \\text{cm}$ de radio y $' + v.R + '\\ \\text{m}\\Omega$ de resistencia está en un campo perpendicular que crece a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Cuánta potencia se disipa en el anillo, en mW?'; },
      function (v) { var e = Math.PI * Math.pow(v.r / 100, 2) * v.dB; return e * e / (v.R / 1000) * 1000; }, '$P = \\varepsilon^2/R$; esa energía la entrega quien hace cambiar el campo.', { unit: 'mW' },
      function (v, LM) { var e = LZ(LM).regionEmf(v.r / 100, 1, v.dB); return e * e / (v.R / 1000) * 1000; }),

    /* ======================= Sentido de la corriente ======================= */
    C('se-caso', 'sentido', 2, function (v) { return 'Una espira está en la página, en ' + caseText(v.k) + '. Vista de frente, ¿en qué sentido circula la corriente inducida?'; }, function (v) { return curOf(v.k); },
      [[function (v) { return otherCur(v.k); }, 'Revisa si el flujo crece o decrece: el campo inducido se opone al cambio.'], ['No circula corriente', 'El campo cambia: el flujo cambia y hay corriente.'], ['Depende del material de la espira', 'El sentido lo fija la ley de Lenz, no el material.']],
      function (v) { return 'El flujo ' + (CS[v.k][1] ? 'crece' : 'decrece') + ': el campo inducido ' + (indOut(v.k) ? 'sale' : 'entra') + ' y la corriente es ' + curOf(v.k).toLowerCase() + '.'; }, { vars: { k: [0, 3, 1] } }),
    C('se-bind', 'sentido', 2, function (v) { return 'Una espira está en ' + caseText(v.k) + '. ¿Hacia dónde apunta el campo inducido en el centro de la espira?'; }, function (v) { return indOut(v.k) ? 'Sale de la página' : 'Entra en la página'; },
      [[function (v) { return indOut(v.k) ? 'Entra en la página' : 'Sale de la página'; }, 'Se opone al cambio: si el flujo crece va al revés del externo; si decrece, igual.'], ['Es paralelo a la página', 'Una espira en la página produce en su centro un campo perpendicular a ella.'], ['No hay campo inducido', 'El flujo cambia: sí hay.']],
      'Oposición al cambio del flujo.', { vars: { k: [0, 3, 1] } }),
    C('se-mano', 'sentido', 1, 'Vista de frente, una corriente antihoraria en una espira produce en su centro un campo que…', 'sale de la página',
      [['entra en la página', 'Antihoraria con la mano derecha: el pulgar sale.'], ['apunta hacia la derecha', 'En el centro, el campo es perpendicular a la espira.'], ['es cero', 'En el centro de una espira con corriente el campo no es cero.']],
      'Regla de la mano derecha.'),
    C('se-mano-cw', 'sentido', 1, 'Vista de frente, una corriente horaria en una espira produce en su centro un campo que…', 'entra en la página',
      [['sale de la página', 'Horaria: el pulgar entra.'], ['gira alrededor del centro', 'En el centro el campo es perpendicular a la espira.'], ['apunta hacia arriba en la página', 'Es perpendicular a la página.']],
      'Regla de la mano derecha.'),
    C('se-constante', 'sentido', 1, 'Una espira está quieta en un campo uniforme y constante que sale de la página. La corriente inducida es…', 'cero',
      [['antihoraria', 'Un campo constante no induce nada.'], ['horaria', 'Sin cambio de flujo no hay corriente.'], ['alterna', 'No hay ningún cambio.']],
      'Sin $d\\Phi/dt$ no hay corriente.'),
    C('se-entra-region', 'sentido', 2, 'Una espira entra a velocidad constante a una región donde el campo sale de la página (afuera no hay campo). Mientras entra, vista de frente, la corriente es…', 'horaria',
      [['antihoraria', 'El flujo hacia afuera crece: el inducido entra → horaria.'], ['cero', 'Mientras cruza el borde, el flujo cambia.'], ['horaria y luego antihoraria', 'Mientras entra, el sentido no cambia.']],
      'Flujo que sale y crece → campo inducido que entra.'),
    C('se-dentro-region', 'sentido', 2, 'Una espira ya está completamente dentro de una región de campo uniforme y sigue moviéndose sin girar. La corriente inducida es…', 'cero, porque el flujo ya no cambia',
      [['máxima, porque está dentro del campo', 'Lo que cuenta es el cambio de flujo, no estar dentro.'], ['la misma que mientras entraba', 'Mientras entraba el flujo cambiaba; ahora no.'], ['de sentido contrario al de la entrada', 'Ahora no hay corriente.']],
      'Flujo constante → sin corriente.'),
    C('se-sale-region', 'sentido', 3, 'Una espira sale de una región donde el campo entra en la página. Mientras sale, vista de frente, la corriente es…', 'horaria',
      [['antihoraria', 'El flujo hacia adentro decrece: el inducido entra también → horaria.'], ['cero', 'Mientras cruza el borde el flujo cambia.'], ['antihoraria al principio y horaria al final', 'Mientras sale, el sentido no cambia.']],
      'Flujo que entra y decrece → campo inducido que entra.'),
    C('se-iman-detras', 'sentido', 3, 'Un imán está detrás de la página, sobre el eje de una espira, con su polo N hacia la espira, y se aleja. Visto desde el frente, la corriente inducida es…', 'antihoraria',
      [['horaria', 'El campo del imán en la espira sale (hacia ti) y decrece: el inducido también sale → antihoraria.'], ['cero', 'El flujo cambia mientras se aleja.'], ['depende de la rapidez', 'La rapidez cambia el tamaño, no el sentido.']],
      'Sale y decrece → el inducido sale.'),
    C('se-iman-S', 'sentido', 3, 'Un imán detrás de la página, con su polo S hacia la espira, se acerca. Visto de frente, la corriente inducida es…', 'antihoraria',
      [['horaria', 'Con S hacia la espira, el campo en ella entra; al acercarse crece, y el inducido sale → antihoraria.'], ['cero', 'Se acerca: el flujo cambia.'], ['horaria al principio y antihoraria después', 'Mientras se acerca el sentido no cambia.']],
      'El campo entra y crece → el inducido sale.'),
    C('se-giro', 'sentido', 3, 'Una espira con su normal paralela a un campo que sale de la página empieza a girar sobre un diámetro. En el primer cuarto de vuelta la corriente, vista de frente, es…', 'antihoraria',
      [['horaria', 'El flujo hacia afuera disminuye: el inducido sale → antihoraria.'], ['cero, porque el campo no cambia', 'El ángulo cambia, y con él el flujo.'], ['siempre horaria', 'Se invierte cada media vuelta.']],
      'Sale y decrece (por el ángulo).'),
    C('se-dos-espiras', 'sentido', 3, 'Dos espiras están una frente a otra. Cierras un interruptor y en la primera empieza a circular corriente antihoraria (vista desde la segunda). En la segunda, vista igual, la corriente inducida es…', 'horaria',
      [['antihoraria', 'El flujo de la primera en la segunda crece: la segunda se opone con corriente al revés.'], ['cero', 'Mientras la corriente de la primera crece, el flujo cambia.'], ['antihoraria y cada vez mayor', 'Se opone: va al revés.']],
      'El flujo crece en la segunda espira, que se opone.'),
    C('se-expande', 'sentido', 2, 'Una espira elástica está en un campo que entra en la página y la estiras para que su área crezca. Vista de frente, la corriente inducida es…', 'antihoraria',
      [['horaria', 'El flujo hacia adentro crece: el inducido sale → antihoraria.'], ['cero, porque B no cambia', 'Cambia el área, y con ella el flujo.'], ['depende del material', 'El sentido lo fija Lenz.']],
      'Entra y crece → el inducido sale.'),
    C('se-recipe', 'sentido', 1, '¿Qué es lo primero que debes decidir para hallar el sentido de una corriente inducida?', 'Si el flujo crece, decrece o no cambia',
      [['Si la espira es de cobre o de aluminio', 'El material no decide el sentido.'], ['Cuánto vale la resistencia', 'La resistencia cambia el tamaño, no el sentido.'], ['El valor exacto de B', 'Importa cómo cambia, no cuánto vale.']],
      'Lenz: oposición al cambio.'),

    /* ======================= Campo eléctrico inducido ======================= */
    C('ce-existe', 'campoE', 1, 'Un campo magnético que cambia con el tiempo produce…', 'un campo eléctrico inducido, aunque no haya cargas ni alambres',
      [['solo una corriente si hay un alambre; sin alambre no hay nada', 'El campo eléctrico existe aunque no haya alambre.'], ['un campo eléctrico solo dentro de los imanes', 'Aparece en todo el espacio alrededor.'], ['un campo gravitacional', 'Es un campo eléctrico.']],
      'Forma general de Faraday.'),
    C('ce-ecuacion', 'campoE', 1, 'La forma general de la ley de Faraday es…', '$\\oint \\vec E\\cdot d\\vec l = -\\dfrac{d\\Phi_B}{dt}$',
      [['$\\oint \\vec E\\cdot d\\vec l = 0$', 'Eso vale para el campo de cargas en reposo, no para el inducido.'], ['$\\oint \\vec B\\cdot d\\vec l = \\mu_0 I$', 'Esa es la ley de Ampère.'], ['$\\oint \\vec B\\cdot d\\vec A = 0$', 'Esa es la ley de Gauss del magnetismo.']],
      'La circulación de $\\vec E$ es menos el cambio del flujo.'),
    C('ce-lineas', 'campoE', 2, '¿Cómo son las líneas del campo eléctrico inducido en una región circular con un campo magnético uniforme que cambia?', 'Círculos cerrados alrededor del centro',
      [['Rectas que salen del centro', 'Así son las de una carga puntual, no las del campo inducido.'], ['Paralelas al campo magnético', 'Están en el plano perpendicular a $\\vec B$.'], ['Empiezan en cargas positivas', 'No hay cargas: las líneas se cierran.']],
      'Por simetría, $\\vec E$ es tangente a círculos.'),
    C('ce-conservativo', 'campoE', 3, '¿Por qué el campo eléctrico inducido no se puede describir con un potencial eléctrico?', 'Porque su circulación en un camino cerrado no es cero',
      [['Porque es demasiado débil', 'El tamaño no importa.'], ['Porque no ejerce fuerza sobre las cargas', 'Sí ejerce fuerza: por eso hay corriente.'], ['Porque solo existe dentro de los conductores', 'Existe en todo el espacio.']],
      'Un campo con potencial tendría $\\oint \\vec E\\cdot d\\vec l = 0$.'),
    C('ce-afuera', 'campoE', 2, 'Fuera de un solenoide largo el campo magnético es prácticamente cero. Si la corriente del solenoide cambia, ¿hay campo eléctrico afuera?', 'Sí: un camino que rodea al solenoide encierra un flujo que cambia',
      [['No, porque afuera $B = 0$', 'Importa el flujo que encierra el camino, no el $B$ en el camino.'], ['Solo si hay un alambre afuera', 'El campo existe sin alambre.'], ['Sí, pero paralelo al eje', 'Es tangente a círculos alrededor del eje.']],
      '$E(2\\pi r) = \\pi R^2\\,dB/dt$ afuera.'),
    C('ce-max', 'campoE', 3, 'En una región circular de radio $R$ con un campo uniforme que cambia, ¿dónde es máximo el campo eléctrico inducido?', 'En el borde de la región, $r = R$',
      [['En el centro', 'En el centro $E = 0$: crece con $r$ hasta el borde.'], ['Muy lejos de la región', 'Afuera baja como $1/r$.'], ['Es igual en todas partes', 'Depende de $r$.']],
      'Crece como $r$ adentro y baja como $1/r$ afuera.'),
    C('ce-centro', 'campoE', 2, 'En el centro de una región circular con un campo magnético uniforme que cambia, el campo eléctrico inducido vale…', 'cero',
      [['lo máximo', 'Es máximo en el borde.'], ['$\\frac{R}{2}\\,dB/dt$', 'Ese es su valor en el borde.'], ['infinito', 'Vale cero por simetría.']],
      '$E = (r/2)\\,dB/dt$ con $r = 0$.'),
    N('ce-adentro', 'campoE', 1, { r: [1, 5, 1], dB: [0.5, 5, 0.5] },
      function (v) { return 'Dentro de un solenoide largo, el campo cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Qué campo eléctrico inducido hay a $' + v.r + '\\ \\text{cm}$ del eje (dentro del solenoide), en mV/m?'; },
      function (v) { return v.r / 100 * v.dB / 2 * 1000; }, '$E = (r/2)\\,dB/dt$.',
      { unit: 'mV/m', mistakes: { noHalf: function (v) { return v.r / 100 * v.dB * 1000; } }, feedback: [{ when: 'noHalf', say: 'Falta dividir entre 2.' }] },
      function (v, LM) { return LZ(LM).Einduced(v.r / 100, 1, v.dB) * 1000; }),
    N('ce-afuera-n', 'campoE', 2, { R: [2, 5, 1], r: [6, 20, 2], dB: [0.5, 5, 0.5] },
      function (v) { return 'Un solenoide largo de $' + v.R + '\\ \\text{cm}$ de radio tiene un campo que cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Qué campo eléctrico inducido hay a $' + v.r + '\\ \\text{cm}$ del eje, fuera del solenoide, en mV/m?'; },
      function (v) { return Math.pow(v.R / 100, 2) * v.dB / (2 * v.r / 100) * 1000; }, '$E = R^2/(2r)\\,dB/dt$.',
      { unit: 'mV/m', mistakes: { inside: function (v) { return v.r / 100 * v.dB / 2 * 1000; } }, feedback: [{ when: 'inside', say: 'Esa es la fórmula de adentro.' }] },
      function (v, LM) { return LZ(LM).Einduced(v.r / 100, v.R / 100, v.dB) * 1000; }),
    N('ce-borde', 'campoE', 1, { R: [2, 10, 1], dB: [1, 10, 1] },
      function (v) { return 'En una región circular de $' + v.R + '\\ \\text{cm}$ de radio, el campo magnético cambia a $' + v.dB + '\\ \\text{T/s}$. ¿Qué campo eléctrico inducido hay justo en el borde, en mV/m?'; },
      function (v) { return v.R / 100 * v.dB / 2 * 1000; }, 'En $r = R$: $E = (R/2)\\,dB/dt$.', { unit: 'mV/m' },
      function (v, LM) { return LZ(LM).Einduced(v.R / 100, v.R / 100, v.dB) * 1000; }),
    N('ce-fem-dentro', 'campoE', 1, { r: [1, 5, 1], dB: [0.5, 5, 0.5] },
      function (v) { return 'Una espira de $' + v.r + '\\ \\text{cm}$ de radio está dentro de un solenoide largo, coaxial con él, y el campo cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Cuánto vale $\\oint \\vec E\\cdot d\\vec l$ (la fem), en mV?'; },
      function (v) { return Math.PI * Math.pow(v.r / 100, 2) * v.dB * 1000; }, '$\\pi r^2\\,dB/dt$.', { unit: 'mV' },
      function (v, LM) { return LZ(LM).Einduced(v.r / 100, 1, v.dB) * TAU * v.r / 100 * 1000; }),
    N('ce-fem-fuera', 'campoE', 2, { R: [2, 5, 1], r: [6, 30, 2], dB: [0.5, 5, 0.5] },
      function (v) { return 'Una espira de $' + v.r + '\\ \\text{cm}$ de radio rodea un solenoide largo de $' + v.R + '\\ \\text{cm}$ de radio cuyo campo cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Cuánto vale la fem en la espira, en mV?'; },
      function (v) { return Math.PI * Math.pow(v.R / 100, 2) * v.dB * 1000; }, 'Solo cuenta el flujo dentro del solenoide.',
      { unit: 'mV', mistakes: { big: function (v) { return Math.PI * Math.pow(v.r / 100, 2) * v.dB * 1000; } }, feedback: [{ when: 'big', say: 'Afuera del solenoide no hay campo magnético: el flujo es $\\pi R^2B$.' }] },
      function (v, LM) { return LZ(LM).Einduced(v.r / 100, v.R / 100, v.dB) * TAU * v.r / 100 * 1000; }),
    N('ce-dB', 'campoE', 2, { r: [1, 5, 1], E: [5, 50, 5] },
      function (v) { return 'Dentro de un solenoide largo, a $' + v.r + '\\ \\text{cm}$ del eje, el campo eléctrico inducido mide $' + v.E + '\\ \\text{mV/m}$. ¿A qué ritmo cambia $B$, en T/s?'; },
      function (v) { return 2 * v.E / 1000 / (v.r / 100); }, '$dB/dt = 2E/r$.', { unit: 'T/s' },
      function (v, LM) { return v.E / 1000 / LZ(LM).Einduced(v.r / 100, 1, 1); }),
    N('ce-razon', 'campoE', 3, { R: [2, 6, 1], r: [8, 24, 2] },
      function (v) { return 'En una región de $' + v.R + '\\ \\text{cm}$ de radio, el campo magnético cambia uniformemente. ¿Cuántas veces es mayor el campo eléctrico inducido en el borde ($r = R$) que a $' + v.r + '\\ \\text{cm}$ del centro?'; },
      function (v) { return v.r / v.R; }, 'En el borde $E = (R/2)\\dot B$; afuera $E = R^2\\dot B/(2r)$: el cociente es $r/R$.',
      { unit: '', mistakes: { square: function (v) { return Math.pow(v.r / v.R, 2); } }, feedback: [{ when: 'square', say: 'Afuera el campo baja como $1/r$, no como $1/r^2$.' }] },
      function (v, LM) { return LZ(LM).Einduced(v.R, v.R, 1) / LZ(LM).Einduced(v.r, v.R, 1); }),
    N('ce-electron', 'campoE', 3, { r: [1, 8, 1], dB: [10, 90, 10] },
      function (v) { return 'Un electrón está dentro de una región con campo magnético que cambia a $' + v.dB + '\\ \\text{T/s}$, a $' + v.r + '\\ \\text{cm}$ del centro. ¿Qué fuerza le hace el campo eléctrico inducido, en N?' + SCI; },
      function (v) { return 1.60e-19 * v.r / 100 * v.dB / 2; }, '$F = eE$ con $E = (r/2)\\,dB/dt$.',
      { unit: 'N', mistakes: { noHalf: function (v) { return 1.60e-19 * v.r / 100 * v.dB; } }, feedback: [{ when: 'noHalf', say: 'Adentro, $E = (r/2)\\,dB/dt$: falta el 1/2.' }] },
      function (v, LM) { return 1.60e-19 * LZ(LM).Einduced(v.r / 100, 1, v.dB); }),
    N('ce-trabajo', 'campoE', 3, { R: [2, 5, 1], r: [6, 20, 2], dB: [1, 9, 1] },
      function (v) { return 'Un protón da una vuelta completa en un círculo de $' + v.r + '\\ \\text{cm}$ de radio alrededor de un solenoide de $' + v.R + '\\ \\text{cm}$ de radio, cuyo campo cambia a $' + v.dB + '\\ \\text{T/s}$. ¿Cuánto trabajo le hace el campo eléctrico inducido en esa vuelta, en J?' + SCI; },
      function (v) { return 1.60e-19 * Math.PI * Math.pow(v.R / 100, 2) * v.dB; }, '$W = q\\oint \\vec E\\cdot d\\vec l = q\\,\\pi R^2\\,dB/dt$: no es cero, porque el campo no es conservativo.', { unit: 'J' },
      function (v, LM) { return 1.60e-19 * LZ(LM).Einduced(v.r / 100, v.R / 100, v.dB) * TAU * v.r / 100; }),

    /* ======================= Generadores y fem inversa ======================= */
    C('ge-que', 'generador', 1, 'En un generador de corriente alterna, ¿qué hace que cambie el flujo por la bobina?', 'El giro de la bobina, que cambia el ángulo entre su normal y $\\vec B$',
      [['Un campo magnético que crece sin parar', 'El campo es constante; cambia el ángulo.'], ['La resistencia de la bobina', 'La resistencia no cambia el flujo.'], ['Una pila conectada a la bobina', 'El generador no necesita pila: produce la fem.']],
      '$\\Phi = BA\\cos\\omega t$.'),
    C('ge-max', 'generador', 2, '¿En qué posición es máxima la fem de un generador?', 'Cuando el plano de la bobina es paralelo a $\\vec B$ (flujo cero)',
      [['Cuando el plano de la bobina es perpendicular a $\\vec B$ (flujo máximo)', 'Ahí el flujo está en su pico y no cambia: fem cero.'], ['Siempre vale lo mismo', 'Es senoidal: cambia.'], ['A 45°', 'Es máxima con el plano paralelo a $\\vec B$.']],
      '$\\varepsilon \\propto \\sin\\omega t$.'),
    C('ge-alterna', 'generador', 1, 'La fem de un generador que gira a ritmo constante es…', 'alterna: cambia de signo cada media vuelta',
      [['constante', 'Es senoidal.'], ['siempre positiva', 'Cambia de signo.'], ['creciente con el tiempo', 'Oscila con amplitud fija.']],
      '$\\varepsilon = NBA\\omega\\sin\\omega t$.'),
    C('ge-doble-w', 'generador', 2, 'Si un generador gira el doble de rápido, su fem máxima…', 'se duplica, y también su frecuencia',
      [['se duplica, pero la frecuencia no cambia', 'La frecuencia es la de giro: también se duplica.'], ['no cambia', '$\\varepsilon_{\\max} = NBA\\omega$ crece con $\\omega$.'], ['se cuadruplica', 'Es lineal en $\\omega$.']],
      '$\\varepsilon_{\\max} \\propto \\omega$ y $f = \\omega/2\\pi$.'),
    C('ge-cuesta', 'generador', 2, '¿Por qué cuesta más trabajo girar un generador cuando le conectas una carga (un foco)?', 'Porque la corriente inducida produce un torque que se opone al giro (Lenz)',
      [['Porque el foco pesa', 'El peso no tiene que ver.'], ['Porque el campo magnético aumenta', 'El campo es el mismo; aparece corriente.'], ['No cuesta más: es igual', 'Con corriente aparece un torque magnético que frena.']],
      'Sin corriente no hay torque que frene.'),
    C('ge-inversa', 'generador', 2, 'La fem inversa de un motor eléctrico…', 'se opone a la fem de la fuente y crece con la rapidez del motor',
      [['ayuda a la fuente y hace girar más rápido al motor', 'Por Lenz se opone.'], ['solo existe cuando el motor está quieto', 'Aparece al girar: es cero en reposo.'], ['es igual a la fem de la fuente siempre', 'Crece con la rapidez y nunca alcanza del todo a la fuente si hay carga.']],
      'El motor también es un generador.'),
    C('ge-arranque', 'generador', 3, '¿Por qué un motor jala mucha corriente al arrancar?', 'Porque está quieto, no hay fem inversa y solo la resistencia limita la corriente',
      [['Porque al arrancar la resistencia del motor es mayor', 'Al contrario: lo que falta es la fem inversa.'], ['Porque el campo magnético es más fuerte al principio', 'El campo es el mismo.'], ['Porque necesita cargar sus capacitores', 'La razón es la ausencia de fem inversa.']],
      '$I = (\\varepsilon - \\varepsilon_{\\text{inv}})/R$ con $\\varepsilon_{\\text{inv}} = 0$ al arrancar.'),
    C('ge-bloqueo', 'generador', 3, 'Si atoras un motor que estaba girando (por ejemplo, una licuadora con algo trabado), se calienta mucho porque…', 'al detenerse desaparece la fem inversa y la corriente sube',
      [['la fricción del objeto trabado calienta el motor', 'El calentamiento principal es $I^2R$ por la corriente grande.'], ['el campo magnético se apaga', 'El campo sigue; desaparece la fem inversa.'], ['la fem inversa crece', 'Al detenerse, la fem inversa es cero.']],
      'Sin fem inversa, $I = \\varepsilon/R$ es grande.'),
    N('ge-omega', 'generador', 1, { rpm: [300, 3600, 300] },
      function (v) { return 'Un generador gira a $' + v.rpm + '\\ \\text{rpm}$. ¿Cuánto vale su rapidez angular, en rad/s?'; },
      function (v) { return v.rpm * TAU / 60; }, '$\\omega = 2\\pi\\,(\\text{rpm})/60$.',
      { unit: 'rad/s', mistakes: { hz: function (v) { return v.rpm / 60; } }, feedback: [{ when: 'hz', say: 'Esas son vueltas por segundo; multiplica por $2\\pi$.' }] },
      function (v, LM) { return LZ(LM).rpm2omega(v.rpm); }),
    N('ge-pico', 'generador', 1, { N: [10, 200, 10], B: [0.1, 1, 0.1], A: [10, 100, 10], w: [100, 400, 50] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ gira con $\\omega = ' + v.w + '\\ \\text{rad/s}$ en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Cuánto vale la fem máxima, en volts?'; },
      function (v) { return v.N * v.B * v.A * 1e-4 * v.w; }, '$\\varepsilon_{\\max} = NBA\\omega$.',
      { unit: 'V', mistakes: { cm2: function (v) { return v.N * v.B * v.A * v.w; } }, feedback: [{ when: 'cm2', say: 'El área va en m².' }] },
      function (v, LM) { return LZ(LM).generator(v.N, v.B, v.A * 1e-4, v.w, 0).peak; }),
    N('ge-pico-hz', 'generador', 2, { N: [50, 400, 50], B: [0.1, 0.8, 0.1], A: [50, 500, 50], f: [50, 60, 10] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ gira a $' + v.f + '\\ \\text{Hz}$ en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Cuánto vale la fem máxima, en volts?'; },
      function (v) { return v.N * v.B * v.A * 1e-4 * TAU * v.f; }, '$\\omega = 2\\pi f$.',
      { unit: 'V', mistakes: { f: function (v) { return v.N * v.B * v.A * 1e-4 * v.f; } }, feedback: [{ when: 'f', say: 'Usa $\\omega = 2\\pi f$, no $f$.' }] },
      function (v, LM) { return LZ(LM).generator(v.N, v.B, v.A * 1e-4, TAU * v.f, 0).peak; }),
    N('ge-pico-rpm', 'generador', 2, { N: [50, 300, 50], B: [0.1, 0.8, 0.1], r: [5, 15, 1], rpm: [600, 3000, 300] },
      function (v) { return 'Una bobina circular de $' + v.N + '$ vueltas y $' + v.r + '\\ \\text{cm}$ de radio gira a $' + v.rpm + '\\ \\text{rpm}$ en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Cuánto vale la fem máxima, en volts?'; },
      function (v) { return v.N * v.B * Math.PI * Math.pow(v.r / 100, 2) * v.rpm * TAU / 60; }, '$A = \\pi r^2$ y $\\omega = 2\\pi\\,(\\text{rpm})/60$.',
      { unit: 'V', mistakes: { rpm: function (v) { return v.N * v.B * Math.PI * Math.pow(v.r / 100, 2) * v.rpm; } }, feedback: [{ when: 'rpm', say: 'Pasa las rpm a rad/s.' }] },
      function (v, LM) { return LZ(LM).generator(v.N, v.B, Math.PI * Math.pow(v.r / 100, 2), LZ(LM).rpm2omega(v.rpm), 0).peak; }),
    N('ge-t', 'generador', 3, { N: [50, 300, 50], B: [0.1, 0.8, 0.1], A: [50, 400, 50], f: [50, 60, 10], t: [1, 7, 1] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ gira a $' + v.f + '\\ \\text{Hz}$ en $' + fx(v.B, 1) + '\\ \\text{T}$; en $t = 0$ su normal es paralela a $\\vec B$. ¿Cuánto vale la fem en $t = ' + v.t + '\\ \\text{ms}$, en volts? (Puede ser negativa.)'; },
      function (v) { var w = TAU * v.f; return v.N * v.B * v.A * 1e-4 * w * Math.sin(w * v.t / 1000); }, '$\\varepsilon = NBA\\omega\\sin\\omega t$, con el ángulo en radianes.',
      { unit: 'V', where: function (v) { return Math.abs(Math.sin(TAU * v.f * v.t / 1000)) > 0.15; }, mistakes: { cosine: function (v) { var w = TAU * v.f; return v.N * v.B * v.A * 1e-4 * w * Math.cos(w * v.t / 1000); } }, feedback: [{ when: 'cosine', say: 'Si $\\Phi = BA\\cos\\omega t$, la fem va con $\\sin\\omega t$.' }] },
      function (v, LM) { return LZ(LM).generator(v.N, v.B, v.A * 1e-4, TAU * v.f, v.t / 1000).emf; }),
    N('ge-N', 'generador', 2, { B: [0.2, 0.8, 0.1], A: [100, 500, 100], f: [50, 60, 10], E: [100, 300, 50] },
      function (v) { return '¿Cuántas vueltas necesita una bobina de $' + v.A + '\\ \\text{cm}^2$ que gira a $' + v.f + '\\ \\text{Hz}$ en $' + fx(v.B, 1) + '\\ \\text{T}$ para que su fem máxima sea $' + v.E + '\\ \\text{V}$? (Da el número sin redondear.)'; },
      function (v) { return v.E / (v.B * v.A * 1e-4 * TAU * v.f); }, '$N = \\varepsilon_{\\max}/(BA\\omega)$.', { unit: '' },
      function (v, LM) { return v.E / LZ(LM).generator(1, v.B, v.A * 1e-4, TAU * v.f, 0).peak; }),
    N('ge-B', 'generador', 3, { N: [100, 500, 100], A: [50, 300, 50], rpm: [1200, 3600, 600], E: [50, 300, 50] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ gira a $' + v.rpm + '\\ \\text{rpm}$ y da una fem máxima de $' + v.E + '\\ \\text{V}$. ¿Cuánto vale el campo magnético, en T?'; },
      function (v) { return v.E / (v.N * v.A * 1e-4 * v.rpm * TAU / 60); }, '$B = \\varepsilon_{\\max}/(NA\\omega)$.', { unit: 'T' },
      function (v, LM) { return v.E / LZ(LM).generator(v.N, 1, v.A * 1e-4, LZ(LM).rpm2omega(v.rpm), 0).peak; }),
    N('ge-rms', 'generador', 2, { E: [100, 400, 20] },
      function (v) { return 'La fem máxima de un generador es $' + v.E + '\\ \\text{V}$. ¿Cuánto vale su valor eficaz (rms), $\\varepsilon_{\\max}/\\sqrt 2$, en volts?'; },
      function (v) { return v.E / Math.SQRT2; }, 'Para una senoide, $\\varepsilon_{\\text{rms}} = \\varepsilon_{\\max}/\\sqrt 2$.', { unit: 'V' },
      function (v, LM) { return LZ(LM).generator(1, 1, 1, v.E, 0).rms; }),
    N('ge-periodo', 'generador', 1, { f: [20, 120, 10] },
      function (v) { return 'Un generador produce una fem de $' + v.f + '\\ \\text{Hz}$. ¿Cuánto tarda en repetirse (su periodo), en ms?'; },
      function (v) { return 1000 / v.f; }, '$T = 1/f$.', { unit: 'ms' },
      function (v, LM) { return LZ(LM).generator(1, 1, 1, TAU * v.f, 0).T * 1000; }),
    N('ge-inversa-I', 'generador', 3, { E: [12, 120, 12], R: [1, 10, 1], p: [50, 90, 10] },
      function (v) { return 'Un motor de resistencia $' + v.R + '\\ \\Omega$ se conecta a $' + v.E + '\\ \\text{V}$. Girando a su rapidez normal, su fem inversa es el $' + v.p + '\\ \\%$ de la fuente. ¿Qué corriente jala girando, en A?'; },
      function (v) { return v.E * (1 - v.p / 100) / v.R; }, '$I = (\\varepsilon - \\varepsilon_{\\text{inv}})/R$.',
      { unit: 'A', mistakes: { start: function (v) { return v.E / v.R; } }, feedback: [{ when: 'start', say: 'Esa es la corriente de arranque, sin fem inversa.' }] },
      function (v, LM) { return (v.E - LZ(LM).generator(1, 1, v.E * v.p / 100, 1, 0).peak) / v.R; }),
    N('ge-arranque-n', 'generador', 1, { E: [12, 120, 12], R: [1, 10, 1] },
      function (v) { return 'Un motor de resistencia $' + v.R + '\\ \\Omega$ se conecta a $' + v.E + '\\ \\text{V}$. ¿Qué corriente jala en el instante de arrancar, cuando todavía no gira, en A?'; },
      function (v) { return v.E / v.R; }, 'Sin fem inversa, $I = \\varepsilon/R$.', { unit: 'A' },
      function (v, LM) { return (v.E - LZ(LM).generator(0, 1, 1, 1, 0).peak) / v.R; }),

    /* ======================= Más: Lenz ======================= */
    C('le-para-que', 'lenz', 1, 'La ley de Lenz sirve sobre todo para encontrar…', 'el sentido de la corriente inducida',
      [['el tamaño de la fem inducida', 'El tamaño sale de $N\\,d\\Phi/dt$; Lenz da el sentido.'], ['la resistencia de la espira', 'No tiene que ver con la resistencia.'], ['el valor del campo magnético', 'Lenz no mide el campo.']],
      'Lenz da el sentido; Faraday, el tamaño.'),
    C('le-sin-cambio', 'lenz', 1, 'Si el flujo por una espira no cambia, la ley de Lenz predice…', 'que no hay corriente inducida',
      [['una corriente horaria', 'Sin cambio no hay nada a qué oponerse.'], ['una corriente antihoraria', 'Sin cambio no hay corriente.'], ['una corriente que crece', 'No hay corriente.']],
      'Sin cambio de flujo no hay corriente.'),
    C('le-freno', 'lenz', 1, 'El freno magnético de una montaña rusa funciona gracias a…', 'corrientes inducidas que, por la ley de Lenz, se oponen al movimiento',
      [['la atracción entre imanes y aluminio', 'El aluminio no es atraído; lo frenan las corrientes inducidas.'], ['la fricción de unas zapatas', 'No hay contacto: es magnético.'], ['la gravedad', 'La gravedad acelera el carro.']],
      'Corrientes de Foucault que frenan.'),
    C('le-anillo-salta', 'lenz', 2, 'Un anillo de aluminio está alrededor del núcleo de una bobina. Al conectar la corriente, el anillo salta. ¿Por qué?', 'La corriente inducida en el anillo se opone al aumento del flujo y la bobina lo repele',
      [['El aluminio es atraído por el imán', 'El aluminio no es ferromagnético.'], ['El anillo se calienta y se dilata', 'El salto es por la repulsión magnética.'], ['La bobina lo atrae hacia arriba', 'Lo repele: el anillo se opone al aumento del flujo.']],
      'El anillo de Thomson.'),
    C('le-anillo-corte', 'lenz', 2, 'Si el anillo de aluminio que salta sobre la bobina tiene un corte, al conectar la corriente…', 'no salta, porque no puede circular corriente en él',
      [['salta más alto', 'Sin corriente no hay repulsión.'], ['salta igual', 'Sin circuito cerrado no hay corriente inducida.'], ['se pega a la bobina', 'Sin corriente no hay fuerza.']],
      'Fem sí; corriente no.'),
    C('le-espira-cae', 'lenz', 2, 'Una espira cae verticalmente y entra a una región con campo magnético horizontal. Mientras entra, la fuerza magnética sobre ella…', 'apunta hacia arriba, frenando la caída',
      [['apunta hacia abajo, acelerándola', 'Por Lenz, se opone al movimiento.'], ['es cero', 'Mientras entra, el flujo cambia y hay corriente.'], ['es horizontal', 'Se opone a la caída: es vertical, hacia arriba.']],
      'Se opone al movimiento que cambia el flujo.'),
    C('le-sostener', 'lenz', 2, 'Cuando el flujo por una espira decrece, el campo inducido…', 'apunta igual que el campo externo, para sostener el flujo',
      [['apunta al revés del campo externo', 'Eso pasa cuando el flujo crece.'], ['es cero', 'Si el flujo cambia, hay campo inducido.'], ['es paralelo al plano de la espira', 'En el centro es perpendicular a la espira.']],
      'Se opone a la disminución.'),
    N('le-calor', 'lenz', 2, { r: [2, 8, 1], dB: [0.5, 3, 0.5], R: [5, 50, 5], t: [1, 5, 1] },
      function (v) { return 'Un anillo de $' + v.r + '\\ \\text{cm}$ de radio y $' + v.R + '\\ \\text{m}\\Omega$ está en un campo perpendicular que crece a $' + fx(v.dB, 1) + '\\ \\text{T/s}$ durante $' + v.t + '\\ \\text{s}$. ¿Cuánto calor se produce en el anillo, en mJ?'; },
      function (v) { var e = Math.PI * Math.pow(v.r / 100, 2) * v.dB; return e * e / (v.R / 1000) * v.t * 1000; }, '$Q = (\\varepsilon^2/R)\\,t$.', { unit: 'mJ' },
      function (v, LM) { var e = LZ(LM).regionEmf(v.r / 100, 1, v.dB); return e * e / (v.R / 1000) * v.t * 1000; }),
    N('le-carga', 'lenz', 2, { r: [2, 8, 1], dB: [0.2, 2, 0.2], R: [5, 50, 5] },
      function (v) { return 'El campo perpendicular a un anillo de $' + v.r + '\\ \\text{cm}$ de radio y $' + v.R + '\\ \\text{m}\\Omega$ aumenta $' + fx(v.dB, 1) + '\\ \\text{T}$. ¿Cuánta carga pasa por el anillo, en C?'; },
      function (v) { return Math.PI * Math.pow(v.r / 100, 2) * v.dB / (v.R / 1000); }, '$Q = \\Delta\\Phi/R$.', { unit: 'C' },
      function (v, LM) { return LZ(LM).regionEmf(v.r / 100, 1, v.dB) / (v.R / 1000); }),
    C('le-superconductor', 'lenz', 3, 'Acercas un imán a un anillo superconductor (resistencia cero). ¿Qué pasa con el flujo a través del anillo?', 'No cambia: la corriente inducida lo mantiene constante',
      [['Crece igual que en un anillo de cobre', 'Sin resistencia, la corriente compensa todo el cambio.'], ['Se vuelve cero de inmediato', 'Se queda en el valor que tenía.'], ['Se duplica', 'La oposición es total: no cambia.']],
      'Con $R = 0$ la oposición es completa.'),

    /* ======================= Más: sentido ======================= */
    C('se-pulgar', 'sentido', 1, 'En la regla de la mano derecha para una espira, si los dedos siguen la corriente, el pulgar indica…', 'el campo magnético en el centro de la espira',
      [['la fuerza sobre la espira', 'Indica el campo.'], ['el sentido de la corriente', 'La corriente la siguen los dedos.'], ['la velocidad de los electrones', 'Indica el campo en el centro.']],
      'Pulgar = $\\vec B$ en el centro.'),
    C('se-atras', 'sentido', 1, 'Una corriente que se ve horaria desde el frente de la página, vista desde atrás, se ve…', 'antihoraria',
      [['horaria', 'Al voltear el punto de vista, los sentidos se intercambian.'], ['detenida', 'Sigue circulando igual.'], ['depende de la corriente', 'Siempre se intercambian.']],
      'Por eso hay que decir desde dónde se mira.'),
    C('se-inverso', 'sentido', 1, 'Si en una espira en un campo que sale de la página se induce corriente horaria (vista de frente), el campo externo…', 'está aumentando',
      [['está disminuyendo', 'Horaria produce un campo que entra: se opone a un aumento del campo que sale.'], ['es constante', 'Si fuera constante no habría corriente.'], ['es cero', 'Hay un campo que sale.']],
      'Inducido contrario al externo → el flujo crece.'),
    C('se-alambre', 'sentido', 2, 'Un alambre largo lleva una corriente hacia arriba que va aumentando. Una espira está a su derecha, en el mismo plano. Vista de frente, la corriente inducida en la espira es…', 'antihoraria',
      [['horaria', 'A la derecha del alambre el campo entra y crece: el inducido sale → antihoraria.'], ['cero', 'La corriente cambia: el flujo cambia.'], ['paralela al alambre', 'La corriente de la espira circula por la espira.']],
      'Campo del alambre a la derecha: entra en la página.'),
    C('se-alambre-izq', 'sentido', 2, 'Un alambre largo lleva una corriente hacia arriba que va disminuyendo. Una espira está a su izquierda, en el mismo plano. Vista de frente, la corriente inducida es…', 'antihoraria',
      [['horaria', 'A la izquierda el campo del alambre sale; al disminuir, el inducido también sale → antihoraria.'], ['cero', 'La corriente cambia.'], ['horaria, porque la corriente disminuye', 'Depende también de hacia dónde apunta el campo.']],
      'Sale y decrece → el inducido sale.'),
    C('se-alambre-aleja', 'sentido', 2, 'Una espira está a la derecha de un alambre largo con corriente constante hacia arriba, en el mismo plano, y se aleja del alambre. Vista de frente, la corriente inducida es…', 'horaria',
      [['antihoraria', 'El campo (que entra) disminuye al alejarse: el inducido también entra → horaria.'], ['cero, porque la corriente del alambre es constante', 'La espira se mueve a donde el campo es menor: el flujo cambia.'], ['antihoraria y luego horaria', 'Mientras se aleja, el sentido no cambia.']],
      'Entra y decrece → el inducido entra.'),
    C('se-alambre-paralelo', 'sentido', 2, 'Una espira se mueve paralela a un alambre largo con corriente constante, sin acercarse ni alejarse. La corriente inducida es…', 'cero',
      [['horaria', 'La distancia no cambia: el flujo no cambia.'], ['antihoraria', 'Sin cambio de flujo no hay corriente.'], ['alterna', 'No hay cambio.']],
      'El campo solo depende de la distancia al alambre.'),
    C('se-solenoide', 'sentido', 2, 'Un anillo rodea un solenoide largo, coaxial con él. Si la corriente del solenoide aumenta, la corriente inducida en el anillo circula…', 'en sentido contrario a la del solenoide',
      [['en el mismo sentido que la del solenoide', 'Eso reforzaría el aumento del flujo.'], ['a lo largo del eje', 'Circula por el anillo.'], ['no hay corriente, porque afuera B = 0', 'El anillo encierra el flujo del solenoide, que cambia.']],
      'Se opone al aumento.'),
    C('se-solenoide-baja', 'sentido', 2, 'Un anillo rodea un solenoide largo, coaxial con él. Si la corriente del solenoide disminuye, la corriente inducida en el anillo circula…', 'en el mismo sentido que la del solenoide',
      [['en sentido contrario a la del solenoide', 'Cuando el flujo decrece, el inducido lo sostiene: mismo sentido.'], ['no hay corriente', 'El flujo encerrado cambia.'], ['a lo largo del eje', 'Circula por el anillo.']],
      'Sostiene el flujo que disminuye.'),
    C('se-abre', 'sentido', 3, 'Dos espiras están una frente a otra. En la primera circula una corriente antihoraria (vista desde la segunda) y abres su interruptor. En la segunda, vista igual, aparece por un instante una corriente…', 'antihoraria',
      [['horaria', 'El flujo en la segunda disminuye: la inducida lo sostiene con el mismo sentido.'], ['cero', 'Al abrir, el flujo cae rápido: hay corriente.'], ['horaria y cada vez mayor', 'Es un pulso en el mismo sentido.']],
      'Al apagar, la segunda espira sostiene el flujo.'),

    /* ======================= Más: campo eléctrico inducido ======================= */
    C('ce-cargas', 'campoE', 1, '¿Las líneas del campo eléctrico inducido empiezan en cargas positivas?', 'No: son líneas cerradas, sin principio ni fin',
      [['Sí, como todas las líneas de campo eléctrico', 'Las del campo inducido se cierran.'], ['Sí, en las cargas del imán', 'Un imán no tiene carga neta.'], ['Empiezan en el polo N', 'Los polos no son cargas.']],
      'Se cierran sobre sí mismas.'),
    C('ce-quien-empuja', 'campoE', 1, 'En una espira quieta dentro de un campo magnético que cambia, ¿qué empuja a las cargas para formar la corriente?', 'El campo eléctrico inducido',
      [['La fuerza magnética $q\\vec v\\times\\vec B$', 'Las cargas parten del reposo: la fuerza magnética sobre ellas es cero.'], ['La gravedad', 'No tiene que ver.'], ['Una pila escondida', 'No hay pila: es inducción.']],
      'Un $\\vec B$ que cambia produce un $\\vec E$.'),
    N('ce-mm', 'campoE', 1, { r: [5, 40, 5], dB: [1, 9, 1] },
      function (v) { return 'En una región con campo magnético uniforme que cambia a $' + v.dB + '\\ \\text{T/s}$, ¿qué campo eléctrico inducido hay a $' + v.r + '\\ \\text{mm}$ del centro (dentro de la región), en V/m?'; },
      function (v) { return v.r / 1000 * v.dB / 2; }, '$E = (r/2)\\,dB/dt$, $r$ en metros.',
      { unit: 'V/m', mistakes: { mm: function (v) { return v.r * v.dB / 2; } }, feedback: [{ when: 'mm', say: 'Pasa los milímetros a metros.' }] },
      function (v, LM) { return LZ(LM).Einduced(v.r / 1000, 1, v.dB); }),
    N('ce-R-desde', 'campoE', 2, { E: [10, 90, 10], dB: [1, 5, 0.5] },
      function (v) { return 'En el borde de una región circular donde $B$ cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$, el campo eléctrico inducido mide $' + v.E + '\\ \\text{mV/m}$. ¿Cuál es el radio de la región, en cm?'; },
      function (v) { return 2 * v.E / 1000 / v.dB * 100; }, 'En el borde $E = (R/2)\\,dB/dt$.', { unit: 'cm' },
      function (v, LM) { return v.E / 1000 / LZ(LM).Einduced(1, 1, v.dB) * 100; }),
    N('ce-proton', 'campoE', 2, { r: [1, 8, 1], dB: [10, 90, 10] },
      function (v) { return 'Un protón está a $' + v.r + '\\ \\text{cm}$ del centro de una región donde el campo magnético cambia a $' + v.dB + '\\ \\text{T/s}$. Con $m_p = 1.67\\times 10^{-27}\\ \\text{kg}$, ¿con qué aceleración arranca por el campo eléctrico inducido, en m/s²?' + SCI; },
      function (v) { return 1.60e-19 * v.r / 100 * v.dB / 2 / 1.67e-27; }, '$a = eE/m_p$ con $E = (r/2)\\,dB/dt$.', { unit: 'm/s²' },
      function (v, LM) { return 1.60e-19 * LZ(LM).Einduced(v.r / 100, 1, v.dB) / 1.67e-27; }),
    N('ce-cuadrado', 'campoE', 2, { s: [2, 10, 1], dB: [0.5, 5, 0.5] },
      function (v) { return 'Un camino cuadrado de $' + v.s + '\\ \\text{cm}$ de lado está completamente dentro de una región donde el campo magnético, perpendicular al cuadrado, cambia a $' + fx(v.dB, 1) + '\\ \\text{T/s}$. ¿Cuánto vale $\\oint \\vec E\\cdot d\\vec l$ alrededor del cuadrado, en mV?'; },
      function (v) { return Math.pow(v.s / 100, 2) * v.dB * 1000; }, 'Solo importa el flujo encerrado: $s^2\\,dB/dt$, sin importar la forma.', { unit: 'mV' },
      function (v, LM) { var r = v.s / 100 / Math.sqrt(Math.PI); return LZ(LM).regionEmf(r, 1, v.dB) * 1000; }),
    C('ce-forma', 'campoE', 2, 'La fem alrededor de un camino cerrado en una región donde $B$ cambia depende de…', 'el flujo que encierra el camino, no de su forma',
      [['la forma del camino, aunque encierre el mismo flujo', 'La ley de Faraday solo pide el flujo encerrado.'], ['el material del camino', 'Vale aunque no haya material.'], ['la longitud del camino solamente', 'Importa el flujo encerrado.']],
      '$\\oint \\vec E\\cdot d\\vec l = -d\\Phi_B/dt$.'),
    C('ce-betatron', 'campoE', 2, 'En un betatrón, los electrones ganan energía dando vueltas porque…', 'el campo eléctrico inducido por un campo magnético que crece los empuja a lo largo de su órbita',
      [['un campo eléctrico estático los acelera', 'Un campo estático no podría acelerarlos vuelta tras vuelta.'], ['la fuerza magnética hace trabajo sobre ellos', 'La fuerza magnética no hace trabajo.'], ['la gravedad los acelera', 'Es un efecto eléctrico.']],
      'El campo inducido sí hace trabajo neto en una vuelta.'),
    C('ce-circula', 'campoE', 2, 'En una región circular el campo magnético sale de la página y crece. Vista de frente, el campo eléctrico inducido circula en sentido…', 'horario',
      [['antihorario', 'Una carga positiva libre circularía como la corriente inducida: horaria (el inducido entra).'], ['radial, hacia afuera', 'Es tangente a círculos.'], ['radial, hacia adentro', 'Es tangente a círculos.']],
      'Igual que la corriente que se induciría en una espira.'),
    N('ce-dB-afuera', 'campoE', 2, { R: [2, 5, 1], r: [6, 20, 2], E: [2, 20, 2] },
      function (v) { return 'A $' + v.r + '\\ \\text{cm}$ del eje de un solenoide largo de $' + v.R + '\\ \\text{cm}$ de radio, el campo eléctrico inducido mide $' + v.E + '\\ \\text{mV/m}$. ¿A qué ritmo cambia el campo dentro del solenoide, en T/s?'; },
      function (v) { return v.E / 1000 * 2 * (v.r / 100) / Math.pow(v.R / 100, 2); }, 'Afuera $E = R^2\\dot B/(2r)$ → $\\dot B = 2rE/R^2$.', { unit: 'T/s' },
      function (v, LM) { return v.E / 1000 / LZ(LM).Einduced(v.r / 100, v.R / 100, 1); }),

    /* ======================= Más: generadores ======================= */
    C('ge-energia', 'generador', 1, 'En un generador, la energía eléctrica sale de…', 'el trabajo de quien hace girar la bobina (una turbina, por ejemplo)',
      [['el imán, que se va descargando', 'El imán no se gasta.'], ['la resistencia de la bobina', 'La resistencia disipa energía; no la produce.'], ['la nada: el generador es gratis', 'La energía se conserva.']],
      'Trabajo mecánico → energía eléctrica.'),
    C('ge-frecuencia', 'generador', 1, 'Una bobina gira a 50 vueltas por segundo en un campo uniforme. ¿Qué frecuencia tiene su fem?', '50 Hz',
      [['100 Hz', 'Una vuelta = un ciclo completo de la fem.'], ['25 Hz', 'La frecuencia es la del giro.'], ['314 Hz', 'Eso es $\\omega$ en rad/s, no la frecuencia.']],
      '$f$ = vueltas por segundo.'),
    N('ge-hz', 'generador', 1, { rpm: [600, 4200, 600] },
      function (v) { return 'Un generador gira a $' + v.rpm + '\\ \\text{rpm}$. ¿Qué frecuencia tiene su fem, en Hz?'; },
      function (v) { return v.rpm / 60; }, '$f = \\text{rpm}/60$.', { unit: 'Hz' },
      function (v, LM) { return LZ(LM).generator(1, 1, 1, LZ(LM).rpm2omega(v.rpm), 0).f; }),
    N('ge-pico-m2', 'generador', 1, { N: [10, 100, 10], B: [0.1, 0.9, 0.1], A: [0.01, 0.05, 0.01], w: [50, 400, 50] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + fx(v.A, 2) + '\\ \\text{m}^2$ gira con $\\omega = ' + v.w + '\\ \\text{rad/s}$ en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Cuánto vale su fem máxima, en V?'; },
      function (v) { return v.N * v.B * v.A * v.w; }, '$\\varepsilon_{\\max} = NBA\\omega$.', { unit: 'V' },
      function (v, LM) { return LZ(LM).generator(v.N, v.B, v.A, v.w, 0).peak; }),
    N('ge-w', 'generador', 2, { N: [50, 300, 50], B: [0.2, 0.8, 0.2], A: [50, 300, 50], E: [20, 200, 20] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ gira en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Con qué rapidez angular debe girar para que su fem máxima sea $' + v.E + '\\ \\text{V}$, en rad/s?'; },
      function (v) { return v.E / (v.N * v.B * v.A * 1e-4); }, '$\\omega = \\varepsilon_{\\max}/(NBA)$.', { unit: 'rad/s' },
      function (v, LM) { return v.E / LZ(LM).generator(v.N, v.B, v.A * 1e-4, 1, 0).peak; }),
    N('ge-rpm', 'generador', 2, { N: [100, 400, 100], B: [0.2, 0.8, 0.2], A: [100, 400, 100], E: [50, 300, 50] },
      function (v) { return '¿A cuántas rpm debe girar una bobina de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ en un campo de $' + fx(v.B, 1) + '\\ \\text{T}$ para dar una fem máxima de $' + v.E + '\\ \\text{V}$?'; },
      function (v) { return v.E / (v.N * v.B * v.A * 1e-4) * 60 / TAU; }, '$\\omega = \\varepsilon_{\\max}/(NBA)$ y rpm $= 60\\,\\omega/2\\pi$.',
      { unit: 'rpm', mistakes: { rad: function (v) { return v.E / (v.N * v.B * v.A * 1e-4); } }, feedback: [{ when: 'rad', say: 'Eso está en rad/s; pásalo a rpm.' }] },
      function (v, LM) { return v.E / LZ(LM).generator(v.N, v.B, v.A * 1e-4, LZ(LM).rpm2omega(1), 0).peak; }),
    N('ge-area', 'generador', 2, { N: [50, 300, 50], B: [0.2, 0.8, 0.2], f: [50, 60, 10], E: [50, 300, 50] },
      function (v) { return 'Un generador de $' + v.N + '$ vueltas gira a $' + v.f + '\\ \\text{Hz}$ en $' + fx(v.B, 1) + '\\ \\text{T}$. ¿Qué área debe tener cada vuelta para que la fem máxima sea $' + v.E + '\\ \\text{V}$, en cm²?'; },
      function (v) { return v.E / (v.N * v.B * TAU * v.f) * 1e4; }, '$A = \\varepsilon_{\\max}/(NB\\omega)$, luego a cm².', { unit: 'cm²' },
      function (v, LM) { return v.E / LZ(LM).generator(v.N, v.B, 1, TAU * v.f, 0).peak * 1e4; }),
    C('ge-cuarto', 'generador', 2, 'Si la fem de un generador vale cero en $t = 0$, ¿cuándo alcanza su máximo por primera vez?', 'Un cuarto de periodo después',
      [['Medio periodo después', 'A medio periodo vuelve a cero.'], ['Un periodo después', 'En un periodo completo vuelve a cero.'], ['Nunca: siempre vale cero', 'Es senoidal.']],
      '$\\sin\\omega t$ es máximo en $\\omega t = \\pi/2$, o sea $t = T/4$.'),
    C('ge-duplicar', 'generador', 2, 'Para duplicar la fem máxima de un generador sin cambiar su rapidez de giro puedes…', 'duplicar el número de vueltas de la bobina',
      [['duplicar la resistencia de la bobina', 'La resistencia no cambia la fem.'], ['reducir el campo a la mitad', 'Eso la reduce.'], ['duplicar el grosor del alambre', 'No cambia $N$, $B$, $A$ ni $\\omega$.']],
      '$\\varepsilon_{\\max} = NBA\\omega$.'),
    N('ge-instante', 'generador', 3, { E: [50, 300, 50], f: [50, 60, 10], p: [20, 90, 10] },
      function (v) { return 'Un generador da $\\varepsilon = ' + v.E + '\\sin(2\\pi\\cdot ' + v.f + '\\,t)$ V. ¿En qué instante, después de $t = 0$, la fem llega por primera vez a $' + fx(v.E * v.p / 100, 1) + '\\ \\text{V}$? En ms.'; },
      function (v) { return Math.asin(v.p / 100) / (TAU * v.f) * 1000; }, '$t = \\arcsin(\\varepsilon/\\varepsilon_{\\max})/\\omega$, con el arcoseno en radianes.',
      { unit: 'ms', mistakes: { deg: function (v) { return Math.asin(v.p / 100) * 180 / Math.PI / (TAU * v.f) * 1000; } }, feedback: [{ when: 'deg', say: 'El arcoseno debe salir en radianes para dividir entre $\\omega$.' }] },
      function (v, LM) { var w = TAU * v.f, lo = 0, hi = Math.PI / 2 / w; for (var k = 0; k < 60; k++) { var m = (lo + hi) / 2; if (LZ(LM).generator(1, 1, v.E, w, m).emf / w < v.E * v.p / 100) lo = m; else hi = m; } return (lo + hi) / 2 * 1000; }),
    C('ge-directa', 'generador', 3, 'Para que un generador entregue una corriente que no cambie de sentido (directa), se usa…', 'un conmutador de anillo partido que invierte las conexiones cada media vuelta',
      [['un imán más fuerte', 'Un imán más fuerte no evita que la fem cambie de signo.'], ['una bobina con más vueltas', 'Más vueltas no cambian el signo de la fem.'], ['girar la bobina más despacio', 'Seguiría cambiando de signo, solo que más lento.']],
      'El conmutador rectifica la fem.')
  ];

  K.register({
    'f3.S12.lenz': 'Ley de Lenz y energía',
    'f3.S12.sentido': 'Sentido de la corriente inducida',
    'f3.S12.campoE': 'Campo eléctrico inducido',
    'f3.S12.generador': 'Generadores y fem inversa'
  }, Q);
})();
